import hashlib
import hmac
import re
from urllib.parse import urlparse, urljoin, quote
from flask import Flask, request, redirect, abort, session, g
from markupsafe import escape
from functools import wraps
import secrets

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

TENANT_REGISTRY = {
    "acme": {"domain": "acme.example.com", "allowed_redirects": ["acme.example.com", "cdn.acme.example.com"]},
    "globex": {"domain": "globex.example.com", "allowed_redirects": ["globex.example.com", "assets.globex.example.com"]},
    "initech": {"domain": "initech.example.com", "allowed_redirects": ["initech.example.com"]},
}

REDIRECT_SIGNING_KEY = secrets.token_bytes(32)


def get_tenant_from_host(host):
    """Extract tenant identifier from the request host header."""
    host_clean = host.split(":")[0].lower().strip()
    for tenant_id, config in TENANT_REGISTRY.items():
        if config["domain"] == host_clean:
            return tenant_id, config
    return None, None


def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if "user" not in session:
            abort(401)
        return f(*args, **kwargs)
    return decorated


def normalize_url(url):
    """Normalize a URL for consistent comparison."""
    if not url:
        return None
    url = url.strip()
    # Handle protocol-relative URLs by prepending https
    if url.startswith("//"):
        url = "https:" + url
    # If no scheme, treat as relative
    parsed = urlparse(url)
    if not parsed.scheme:
        return url  # relative URL, safe
    return url


def validate_redirect_target(url, tenant_config):
    """Validate that a redirect URL is within the tenant's allowed domains.

    Security: Only allows redirects to explicitly registered tenant domains.
    Prevents open redirect by checking the hostname against allowlist.
    """
    if not url:
        return False

    normalized = normalize_url(url)
    if normalized is None:
        return False

    parsed = urlparse(normalized)

    # Allow relative URLs (no host component)
    if not parsed.netloc:
        # Additional check: ensure it doesn't start with backslash or other tricks
        if parsed.path.startswith("\\") or parsed.path.startswith("//"):
            return False
        return True

    # Reject non-http(s) schemes
    if parsed.scheme not in ("https", "http"):
        return False

    # Extract hostname, strip port
    target_host = parsed.netloc.split(":")[0].lower().strip()

    # Reject if target_host contains special characters (anti-bypass)
    if not re.match(r'^[a-z0-9.-]+$', target_host):
        return False

    # Check against tenant's allowed redirect domains (exact match only)
    allowed = tenant_config.get("allowed_redirects", [])

    for allowed_domain in allowed:
        if target_host == allowed_domain:
            return True

    return False


def sign_redirect(url, tenant_id):
    """Create an HMAC signature for a validated redirect URL."""
    msg = f"{tenant_id}:{url}".encode()
    return hmac.new(REDIRECT_SIGNING_KEY, msg, hashlib.sha256).hexdigest()


def verify_redirect_signature(url, tenant_id, signature):
    """Verify HMAC signature of a redirect URL."""
    expected = sign_redirect(url, tenant_id)
    return hmac.compare_digest(expected, signature)


@app.before_request
def set_tenant():
    tenant_id, tenant_config = get_tenant_from_host(request.host)
    if tenant_id is None:
        abort(404)
    g.tenant_id = tenant_id
    g.tenant_config = tenant_config


@app.route("/login", methods=["GET", "POST"])
def login():
    next_url = request.args.get("next", "/")

    if request.method == "POST":
        # Simulate authentication
        username = request.form.get("username", "")
        password = request.form.get("password", "")

        if username and password:  # Simplified auth
            session["user"] = username
            session["tenant"] = g.tenant_id

            # Validate the redirect target before redirecting
            if validate_redirect_target(next_url, g.tenant_config):
                return redirect(next_url)
            else:
                return redirect("/")

    # HTML-escape the reflected value to prevent XSS in the attribute context
    return f'<form method="POST"><input name="username"><input name="password" type="password"><input type="hidden" name="next" value="{escape(next_url)}"><button>Login</button></form>'


@app.route("/oauth/callback")
def oauth_callback():
    """Handle OAuth callback with redirect.

    The state parameter contains the original redirect destination,
    signed to prevent tampering.
    """
    state = request.args.get("state", "")
    redirect_url = request.args.get("redirect_uri", "/")
    sig = request.args.get("sig", "")

    # Always validate against tenant allowlist regardless of signature
    if not validate_redirect_target(redirect_url, g.tenant_config):
        return redirect("/")

    # For signed redirects, also verify signature for integrity
    if sig:
        if not verify_redirect_signature(redirect_url, g.tenant_id, sig):
            return redirect("/")

    session["user"] = "oauth_user"
    session["tenant"] = g.tenant_id
    return redirect(redirect_url)


@app.route("/logout")
@require_auth
def logout():
    return_url = request.args.get("return", "/")
    session.clear()

    if validate_redirect_target(return_url, g.tenant_config):
        return redirect(return_url)
    return redirect("/")


@app.route("/")
def index():
    user = session.get("user", "anonymous")
    return f"<h1>Welcome {escape(user)} to {escape(g.tenant_id)}</h1>"


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8080)
